@import "@fontsource-variable/hanken-grotesk";
@import "@fontsource-variable/geist-mono";

/* Light sibling: a cool off-white page (#f4f5f9), white cards, Mercury's ink (#171721) as
   text, the same periwinkle CTA. */
:root {
  --background: oklch(0.971 0.005 275);
  --foreground: oklch(0.209 0.02 285);
  --card: oklch(1 0 0);
  --card-foreground: oklch(0.209 0.02 285);
  --popover: oklch(0.945 0.008 280);
  --popover-foreground: oklch(0.209 0.02 285);
  --primary: oklch(0.57 0.2 272);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.915 0.012 280);
  --secondary-foreground: oklch(0.209 0.02 285);
  --muted: oklch(0.945 0.008 280);
  --muted-foreground: oklch(0.44 0.02 285);
  --accent: oklch(0.89 0.02 275);
  --accent-foreground: oklch(0.209 0.02 285);
  --destructive: oklch(0.58 0.2 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.209 0.02 285 / 16%);
  --input: oklch(0.209 0.02 285 / 14%);
  --ring: oklch(0.57 0.2 272);
  --highlight: oklch(0.62 0.15 268);
  --highlight-foreground: oklch(1 0 0);
  --glow: oklch(0.72 0.1 265);
  --chart-1: oklch(0.57 0.2 272);
  --chart-2: oklch(0.8 0.06 30);
  --chart-3: oklch(0.86 0.03 229);
  --chart-4: oklch(0.62 0.06 140);
  --chart-5: oklch(0.935 0.012 95);
  --sidebar: oklch(0.985 0.003 275);
  --sidebar-foreground: oklch(0.209 0.02 285);
  --sidebar-primary: oklch(0.57 0.2 272);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.945 0.008 280);
  --sidebar-accent-foreground: oklch(0.209 0.02 285);
  --sidebar-border: oklch(0.209 0.02 285 / 12%);
  --sidebar-ring: oklch(0.57 0.2 272);

  --typeface-body: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-display: "Hanken Grotesk Variable", ui-sans-serif, system-ui, sans-serif;
  --typeface-mono: "Geist Mono Variable", ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  --radius: 0.75rem;
  --page-width: 67rem;
  --page-gutter: 1.5rem;
  --section-y: 7.5rem;
}

/* Dark (faithful): the #171721 ink page, #1e1e2a cards, #272735 tiles, soft #ededf3
   text, #c3c3cc secondary text, the #5266eb periwinkle CTA and a pale-blue (#cdddff)
   bullet dot. Hairlines are a translucent lavender. */
.dark {
  --background: oklch(0.209 0.02 285);
  --foreground: oklch(0.948 0.008 286);
  --card: oklch(0.241 0.023 285);
  --card-foreground: oklch(0.948 0.008 286);
  --popover: oklch(0.279 0.026 285);
  --popover-foreground: oklch(0.948 0.008 286);
  --primary: oklch(0.57 0.2 272);
  --primary-foreground: oklch(1 0 0);
  --secondary: oklch(0.338 0.025 282);
  --secondary-foreground: oklch(0.948 0.008 286);
  --muted: oklch(0.279 0.026 285);
  --muted-foreground: oklch(0.82 0.012 286);
  --accent: oklch(0.38 0.03 280);
  --accent-foreground: oklch(0.948 0.008 286);
  --destructive: oklch(0.66 0.19 25);
  --destructive-foreground: oklch(1 0 0);
  --border: oklch(0.77 0.04 281 / 36%);
  --input: oklch(0.565 0.049 280 / 45%);
  --ring: oklch(0.7 0.13 270);
  --highlight: oklch(0.896 0.05 265);
  --highlight-foreground: oklch(0.209 0.02 285);
  --glow: oklch(0.771 0.079 265);
  --chart-1: oklch(0.62 0.18 272);
  --chart-2: oklch(0.74 0.07 30);
  --chart-3: oklch(0.86 0.03 229);
  --chart-4: oklch(0.5 0.06 140);
  --chart-5: oklch(0.948 0.007 97);
  --sidebar: oklch(0.225 0.022 285);
  --sidebar-foreground: oklch(0.948 0.008 286);
  --sidebar-primary: oklch(0.57 0.2 272);
  --sidebar-primary-foreground: oklch(1 0 0);
  --sidebar-accent: oklch(0.279 0.026 285);
  --sidebar-accent-foreground: oklch(0.948 0.008 286);
  --sidebar-border: oklch(0.77 0.04 281 / 22%);
  --sidebar-ring: oklch(0.7 0.13 270);
}
